1	// Acceptance test for the change request:
2	//   "Let me keep a task list on each project. Let me tick things off as I finish them."
3	//
4	// A project keeps a list of tasks. On a project's detail page (/projects/<id>) that list is shown:
5	// each task is its own row (task-row-<id>) carrying its title (task-title) and whether it is done
6	// (task-status). A project with no tasks shows an empty state (project-tasks-empty) instead of the
7	// table (project-tasks-table). Each task offers a control to tick it off / untick it
8	// (task-toggle-<id>); toggling flips whether the task is done, persists across a fresh load, and —
9	// so the change can be checked back later — appends exactly one audit record
10	// `TASK_TOGGLED id=<id> done=<done>` per toggle, carrying the task's id and its NEW done state.
11	// Toggling one task must not touch its siblings. A task's list belongs to ITS project: a task on a
12	// different project is not shown here.
13	//
14	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
15	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
16	// honours { id, name, email }, `projects` honours { id, name, clientId } and `tasks` honours
17	// { id, title, projectId, done }.
18	import { test, expect, type Page, type Locator } from '@playwright/test';
19	import { resetAndSeed } from '../support/seed';
20	import { auditLines } from '../support/audit';
21	
22	// A task's status cell reads "done" when it has been ticked off — matched by the WORD, case
23	// -insensitively, so the test binds to the MEANING and not one capitalisation ("Done"/"DONE"/"done"
24	// all count). A task that is NOT done reads some other way ("To do"/"Pending"/…); the test only
25	// requires that it does NOT read done, rather than pinning that wording.
26	const DONE = /\bdone\b/i;
27	
28	const taskRows = (page: Page) => page.locator('[data-testid^="task-row-"]');
29	const statusOf = (page: Page, id: number): Locator =>
30	  page.getByTestId(`task-row-${id}`).getByTestId('task-status');
31	
32	// The audit record for one toggle. The new done state is written as a boolean, accepted as either
33	// true/false or 1/0 so the test binds to the MEANING; everything else is matched exactly.
34	const toggledRecord = (id: number, done: boolean) =>
35	  new RegExp(`^TASK_TOGGLED id=${id} done=${done ? '(?:true|1)' : '(?:false|0)'}$`);
36	
37	const toggledRecordsFor = (id: number, done: boolean): string[] =>
38	  auditLines().filter((line) => toggledRecord(id, done).test(line));
39	
40	test.describe('A task list on each project', () => {
41	  test('a project with no tasks shows an empty state, not the table', async ({ page }) => {
42	    await resetAndSeed({
43	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
44	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
45	      tasks: [],
46	    });
47	
48	    await page.goto('/projects/1');
49	
50	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
51	    await expect(page.getByTestId('project-tasks-empty')).toBeVisible();
52	    // No tasks yet: no rows, and the table is not shown.
53	    await expect(taskRows(page)).toHaveCount(0);
54	    await expect(page.getByTestId('project-tasks-table')).toHaveCount(0);
55	  });
56	
57	  test('every task on the project is shown with its title and whether it is done', async ({
58	    page,
59	  }) => {
60	    await resetAndSeed({
61	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
62	      projects: [
63	        { id: 1, name: 'Website Redesign', clientId: 1 },
64	        { id: 2, name: 'Mobile App', clientId: 1 },
65	      ],
66	      tasks: [
67	        { id: 1, title: 'Draft the brief', projectId: 1, done: false },
68	        { id: 2, title: 'Build the homepage', projectId: 1, done: true },
69	        { id: 3, title: 'Review with client', projectId: 1, done: false },
70	        // A task on a DIFFERENT project must not show on this project's list.
71	        { id: 4, title: 'Ship to the store', projectId: 2, done: false },
72	      ],
73	    });
74	
75	    await page.goto('/projects/1');
76	
77	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
78	    await expect(page.getByTestId('project-tasks-table')).toBeVisible();
79	    await expect(page.getByTestId('project-tasks-empty')).toHaveCount(0);
80	
81	    // Only this project's three tasks are shown, each carrying its own title.
82	    await expect(taskRows(page)).toHaveCount(3);
83	    await expect(page.getByTestId('task-row-1').getByTestId('task-title')).toHaveText(
84	      'Draft the brief',
85	    );
86	    await expect(page.getByTestId('task-row-2').getByTestId('task-title')).toHaveText(
87	      'Build the homepage',
88	    );
89	    await expect(page.getByTestId('task-row-3').getByTestId('task-title')).toHaveText(
90	      'Review with client',
91	    );
92	
93	    // The seeded done state is reflected: the ticked-off task reads done, the others do not.
94	    await expect(statusOf(page, 2)).toHaveText(DONE);
95	    await expect(statusOf(page, 1)).not.toHaveText(DONE);
96	    await expect(statusOf(page, 3)).not.toHaveText(DONE);
97	
98	    // The other project's task is nowhere on this page.
99	    await expect(page.getByTestId('task-row-4')).toHaveCount(0);
100	    await expect(page.getByTestId('project-detail-page')).not.toContainText('Ship to the store');
101	
102	    // Merely loading the list records nothing — a record is kept when a task is toggled, not on view.
103	    expect(auditLines()).toEqual([]);
104	  });
105	
106	  test('ticking a task off marks it done, persists, and records it once', async ({ page }) => {
107	    await resetAndSeed({
108	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
109	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
110	      tasks: [{ id: 1, title: 'Draft the brief', projectId: 1, done: false }],
111	    });
112	
113	    await page.goto('/projects/1');
114	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
115	
116	    // The task is not yet done, and offers a control to tick it off.
117	    await expect(statusOf(page, 1)).not.toHaveText(DONE);
118	    const toggle = page.getByTestId('task-toggle-1');
119	    await expect(toggle).toBeVisible();
120	
121	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
122	    // toggle (not the seeding) wrote it.
123	    expect(auditLines()).toEqual([]);
124	
125	    await toggle.click();
126	
127	    // It now reads done.
128	    await expect(statusOf(page, 1)).toHaveText(DONE);
129	
130	    // Exactly one record was kept for this toggle, carrying the task's id and its new done state.
131	    expect(toggledRecordsFor(1, true)).toHaveLength(1);
132	    expect(auditLines()).toHaveLength(1);
133	
134	    // The done state is held by the server, not just the page: it survives a fresh load, and
135	    // reloading does not record the toggle a second time.
136	    await page.reload();
137	    await expect(statusOf(page, 1)).toHaveText(DONE);
138	    expect(toggledRecordsFor(1, true)).toHaveLength(1);
139	    expect(auditLines()).toHaveLength(1);
140	  });
141	
142	  test('a task already done can be unticked, which records its new state', async ({ page }) => {
143	    await resetAndSeed({
144	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
145	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
146	      tasks: [{ id: 1, title: 'Draft the brief', projectId: 1, done: true }],
147	    });
148	
149	    await page.goto('/projects/1');
150	
151	    // Seeded as done, so it reads done from the start — and merely loading it records nothing.
152	    await expect(statusOf(page, 1)).toHaveText(DONE);
153	    expect(auditLines()).toEqual([]);
